INSERT INTO `products` (`id`, `category_id`, `name`, `slug`, `tagline`, `description`, `content`, `logo`, `banner_image`, `video_url`, `version`, `download_url`, `is_featured`, `status`, `view_count`, `order`, `translations`, `created_at`, `updated_at`, `seo_title`, `seo_description`, `seo_keywords`, `focus_keyword`, `canonical_url`, `robots_meta`) VALUES
(1, 1, 'LushCare v3.5', 'lush-marketing-pro', 'Phần mềm nuôi và tương tác dàn nick đa kênh tự động hóa số 1 Việt Nam', 'Công cụ hàng đầu giúp tự động hóa quy trình gửi email, tin nhắn Zalo, SMS và thông báo đẩy. Tối ưu chuyển đổi và giảm 70% thời gian thực thi của đội ngũ Marketing.', '<h2>Đột phá năng suất tiếp thị cùng Lush Marketing Pro</h2><p>Lush Marketing Pro là giải pháp cốt lõi dành cho các doanh nghiệp SME và tập đoàn mong muốn chuẩn hóa và tự động hóa quy trình nuôi dưỡng khách hàng tiềm năng. Tích hợp sâu với các kênh liên lạc phổ biến, hệ thống đảm bảo thông điệp của bạn luôn tiếp cận đúng người vào đúng thời điểm vàng.</p><h3>Lợi ích cốt lõi:</h3><ul><li>Phân khúc tệp khách hàng tự động theo hành vi thực tế.</li><li>Kịch bản chăm sóc chuỗi tự động thông minh (Workflow Builder trực quan).</li><li>Báo cáo tỷ lệ chuyển đổi, mở và click theo thời gian thực.</li><li>Tiết kiệm chi phí nhân sự và loại bỏ thao tác thủ công rườm rà.</li></ul>', NULL, 'images/products/LushCare.png', NULL, 'v3.5.2', NULL, 1, 'published', 12454, 1, '{"en":{"name":"Lush Marketing Pro","tagline":"Advanced automation and software ecosystem for scalable business growth.","description":"Empower your team with next-generation automation tools. High performance, zero setup friction, and enterprise-grade security."},"zh":{"name":"Lush Marketing Pro","tagline":"\\u52a9\\u529b\\u4f01\\u4e1a\\u9ad8\\u6548\\u589e\\u957f\\u7684\\u4e0b\\u4e00\\u4ee3\\u8f6f\\u4ef6\\u4e0e\\u81ea\\u52a8\\u5316\\u751f\\u6001\\u7cfb\\u7edf\\u3002","description":"\\u901a\\u8fc7\\u884c\\u4e1a\\u9886\\u5148\\u7684\\u8425\\u9500\\u4e0e\\u5ba2\\u6237\\u5173\\u7cfb\\u81ea\\u52a8\\u5316\\u5de5\\u5177\\u8d4b\\u80fd\\u4e1a\\u52a1\\uff0c\\u517c\\u5177\\u9876\\u7ea7\\u6027\\u80fd\\u4e0e\\u4f01\\u4e1a\\u7ea7\\u5b89\\u5168\\u6027\\u3002"},"ko":{"name":"Lush Marketing Pro","tagline":"\\ube44\\uc988\\ub2c8\\uc2a4 \\ud655\\uc7a5\\uc744 \\uc704\\ud55c \\ucc28\\uc138\\ub300 \\uc790\\ub3d9\\ud654 \\uc18c\\ud504\\ud2b8\\uc6e8\\uc5b4 \\uc194\\ub8e8\\uc158.","description":"\\uace0\\uc131\\ub2a5, \\uc644\\ubcbd\\ud55c \\ubcf4\\uc548, \\uc190\\uc26c\\uc6b4 \\uc0ac\\uc6a9\\uc131\\uc744 \\uac16\\ucd98 \\uc885\\ud569 \\ub9c8\\ucf00\\ud305 \\ubc0f CRM \\uc790\\ub3d9\\ud654 \\ud50c\\ub7ab\\ud3fc\\uc785\\ub2c8\\ub2e4."}}', '2026-10-30 14:15:33', '2026-11-02 01:49:15', 'LushCare v3.5 – Phần Mềm Nuôi Nick Đa Kênh Tự Động Hóa 2026', 'Tự động hóa nuôi nick Facebook, Instagram, TikTok số lượng lớn không checkpoint. Tích hợp AI mô phỏng người dùng thật và hỗ trợ Ultraview 1-1.', 'phan mem nuoi nick facebook, lushcare, tu dong tuong tac nick, khang checkpoint facebook', 'phan mem nuoi nick facebook', 'http://localhost:8000/products/lush-marketing-pro', 'index, follow'),
(2, 2, 'LushLogin Antidetect', 'lush-social-hub', 'Trình duyệt Canvas Antidetect ẩn danh sạch 100% cho đội ngũ chạy Ads & MMO', 'Giải pháp mạnh mẽ quản lý hàng trăm tài khoản Facebook, TikTok, Zalo, Instagram trên một màn hình duy nhất. Tự động lên lịch đăng bài, nuôi tài khoản và trả lời bình luận.', '<h2>Làm chủ mạng xã hội với Lush Social Hub</h2><p>Dành riêng cho các nhà sáng tạo nội dung, chủ shop online và agency truyền thông. Lush Social Hub giải phóng bạn khỏi chuỗi công việc lặp đi lặp lại khi phải quản lý thủ công từng fanpage, profile hay group.</p>', NULL, 'images/products/LushLogin.png', NULL, 'v2.8.4', NULL, 1, 'published', 18901, 2, '{"en":{"name":"Lush Social Hub","tagline":"Advanced automation and software ecosystem for scalable business growth.","description":"Empower your team with next-generation automation tools. High performance, zero setup friction, and enterprise-grade security."},"zh":{"name":"Lush Social Hub","tagline":"\\u52a9\\u529b\\u4f01\\u4e1a\\u9ad8\\u6548\\u589e\\u957f\\u7684\\u4e0b\\u4e00\\u4ee3\\u8f6f\\u4ef6\\u4e0e\\u81ea\\u52a8\\u5316\\u751f\\u6001\\u7cfb\\u7edf\\u3002","description":"\\u901a\\u8fc7\\u884c\\u4e1a\\u9886\\u5148\\u7684\\u8425\\u9500\\u4e0e\\u5ba2\\u6237\\u5173\\u7cfb\\u81ea\\u52a8\\u5316\\u5de5\\u5177\\u8d4b\\u80fd\\u4e1a\\u52a1\\uff0c\\u517c\\u5177\\u9876\\u7ea7\\u6027\\u80fd\\u4e0e\\u4f01\\u4e1a\\u7ea7\\u5b89\\u5168\\u6027\\u3002"},"ko":{"name":"Lush Social Hub","tagline":"\\ube44\\uc988\\ub2c8\\uc2a4 \\ud655\\uc7a5\\uc744 \\uc704\\ud55c \\ucc28\\uc138\\ub300 \\uc790\\ub3d9\\ud654 \\uc18c\\ud504\\ud2b8\\uc6e8\\uc5b4 \\uc194\\ub8e8\\uc158.","description":"\\uace0\\uc131\\ub2a5, \\uc644\\ubcbd\\ud55c \\ubcf4\\uc548, \\uc190\\uc26c\\uc6b4 \\uc0ac\\uc6a9\\uc131\\uc744 \\uac16\\ucd98 \\uc885\\ud569 \\ub9c8\\ucf00\\ud305 \\ubc0f CRM \\uc790\\ub3d9\\ud654 \\ud50c\\ub7ab\\ud3fc\\uc785\\ub2c8\\ub2e4."}}', '2026-10-30 14:15:33', '2026-11-02 01:44:16', 'LushLogin Antidetect – Trình Duyệt Ẩn Danh Canvas Sạch 100%', 'Trình duyệt Antidetect Browser thế hệ mới: giả lập vân tay Canvas, WebGL, WebRTC, cô lập 1000+ profiles trên một máy tính và tối ưu RAM cực nhẹ.', 'trinh duyet antidetect browser, lushlogin, antidetect browser mmo, gia lap van tay trinh duyet', 'trinh duyet antidetect browser', 'http://localhost:8000/products/lush-social-hub', 'index, follow'),
(3, 3, 'LushCRM Enterprise', 'lush-crm-enterprise', 'Nền tảng CRM đa kênh tự động phân bổ leads và chăm sóc khách hàng 24/7', 'Phần mềm CRM chuyên sâu cho đội ngũ kinh doanh B2B và B2C. Quản lý toàn diện dữ liệu khách hàng từ lúc phát sinh nhu cầu đến khi hoàn tất hợp đồng và tái mua.', '<h2>Đột phá doanh thu với quy trình bán hàng khép kín</h2><p>Lush CRM Enterprise loại bỏ tình trạng thất thoát lead, hỗ trợ quản lý phân quyền chặt chẽ theo cấp bậc và minh bạch hóa hiệu suất của từng nhân viên kinh doanh.</p>', NULL, 'images/products/LushCRM.png', NULL, 'v4.0.1', NULL, 1, 'published', 9800, 3, '{"en":{"name":"Lush CRM Enterprise","tagline":"Advanced automation and software ecosystem for scalable business growth.","description":"Empower your team with next-generation automation tools. High performance, zero setup friction, and enterprise-grade security."},"zh":{"name":"Lush CRM Enterprise","tagline":"\\u52a9\\u529b\\u4f01\\u4e1a\\u9ad8\\u6548\\u589e\\u957f\\u7684\\u4e0b\\u4e00\\u4ee3\\u8f6f\\u4ef6\\u4e0e\\u81ea\\u52a8\\u5316\\u751f\\u6001\\u7cfb\\u7edf\\u3002","description":"\\u901a\\u8fc7\\u884c\\u4e1a\\u9886\\u5148\\u7684\\u8425\\u9500\\u4e0e\\u5ba2\\u6237\\u5173\\u7cfb\\u81ea\\u52a8\\u5316\\u5de5\\u5177\\u8d4b\\u80fd\\u4e1a\\u52a1\\uff0c\\u517c\\u5177\\u9876\\u7ea7\\u6027\\u80fd\\u4e0e\\u4f01\\u4e1a\\u7ea7\\u5b89\\u5168\\u6027\\u3002"},"ko":{"name":"Lush CRM Enterprise","tagline":"\\ube44\\uc988\\ub2c8\\uc2a4 \\ud655\\uc7a5\\uc744 \\uc704\\ud55c \\ucc28\\uc138\\ub300 \\uc790\\ub3d9\\ud654 \\uc18c\\ud504\\ud2b8\\uc6e8\\uc5b4 \\uc194\\ub8e8\\uc158.","description":"\\uace0\\uc131\\ub2a5, \\uc644\\ubcbd\\ud55c \\ubcf4\\uc548, \\uc190\\uc26c\\uc6b4 \\uc0ac\\uc6a9\\uc131\\uc744 \\uac16\\ucd98 \\uc885\\ud569 \\ub9c8\\ucf00\\ud305 \\ubc0f CRM \\uc790\\ub3d9\\ud654 \\ud50c\\ub7ab\\ud3fc\\uc785\\ub2c8\\ub2e4."}}', '2026-10-30 14:15:33', '2026-11-02 01:44:16', 'LushCRM Enterprise – Nền Tảng CRM & Bán Hàng Tự Động Đa Kênh', 'Gom toàn bộ tin nhắn Facebook, Zalo, Website về một giao diện tập trung, tự động chia leads cho nhân viên sales và remarketing tự động x3 doanh số.', 'phan mem crm da kenh, lushcrm enterprise, quan ly ban hang tu dong, cham soc khach hang crm', 'phan mem crm da kenh', 'http://localhost:8000/products/lush-crm-enterprise', 'index, follow'),
(4, 4, 'LushZalo Marketing', 'lush-data-scraper', 'Giải pháp tự động hóa kết bạn, gửi tin nhắn và chăm sóc khách hàng Zalo', 'Công cụ thu thập dữ liệu tự động từ các nền tảng thương mại điện tử, mạng xã hội và danh bạ doanh nghiệp. Cung cấp dữ liệu insight quý giá phục vụ nghiên cứu thị trường.', '<h2>Nắm bắt insight thị trường chính xác từng giây</h2><p>Lush Data Scraper giúp doanh nghiệp nghiên cứu giá bán đối thủ, thị hiếu khách hàng và danh sách khách hàng tiềm năng một cách nhanh chóng, chuẩn xác và hợp pháp.</p>', NULL, 'images/products/LushZalo.png', NULL, 'v2.5.0', NULL, 0, 'published', 8400, 4, '{"en":{"name":"Lush Data Scraper","tagline":"Advanced automation and software ecosystem for scalable business growth.","description":"Empower your team with next-generation automation tools. High performance, zero setup friction, and enterprise-grade security."},"zh":{"name":"Lush Data Scraper","tagline":"\\u52a9\\u529b\\u4f01\\u4e1a\\u9ad8\\u6548\\u589e\\u957f\\u7684\\u4e0b\\u4e00\\u4ee3\\u8f6f\\u4ef6\\u4e0e\\u81ea\\u52a8\\u5316\\u751f\\u6001\\u7cfb\\u7edf\\u3002","description":"\\u901a\\u8fc7\\u884c\\u4e1a\\u9886\\u5148\\u7684\\u8425\\u9500\\u4e0e\\u5ba2\\u6237\\u5173\\u7cfb\\u81ea\\u52a8\\u5316\\u5de5\\u5177\\u8d4b\\u80fd\\u4e1a\\u52a1\\uff0c\\u517c\\u5177\\u9876\\u7ea7\\u6027\\u80fd\\u4e0e\\u4f01\\u4e1a\\u7ea7\\u5b89\\u5168\\u6027\\u3002"},"ko":{"name":"Lush Data Scraper","tagline":"\\ube44\\uc988\\ub2c8\\uc2a4 \\ud655\\uc7a5\\uc744 \\uc704\\ud55c \\ucc28\\uc138\\ub300 \\uc790\\ub3d9\\ud654 \\uc18c\\ud504\\ud2b8\\uc6e8\\uc5b4 \\uc194\\ub8e8\\uc158.","description":"\\uace0\\uc131\\ub2a5, \\uc644\\ubcbd\\ud55c \\ubcf4\\uc548, \\uc190\\uc26c\\uc6b4 \\uc0ac\\uc6a9\\uc131\\uc744 \\uac16\\ucd98 \\uc885\\ud569 \\ub9c8\\ucf00\\ud305 \\ubc0f CRM \\uc790\\ub3d9\\ud654 \\ud50c\\ub7ab\\ud3fc\\uc785\\ub2c8\\ub2e4."}}', '2026-10-30 14:15:33', '2026-11-02 01:44:16', 'LushZalo Marketing – Tự Động Kết Bạn & Chăm Sóc Khách Hàng Zalo', 'Phần mềm Zalo Marketing tự động: kết bạn theo số điện thoại, gửi tin nhắn hàng loạt theo tệp data và quản lý hàng chục tài khoản Zalo không lo khóa.', 'phan mem zalo marketing, lushzalo marketing, ket ban zalo tu dong, gui tin nhan zalo hang loat', 'phan mem zalo marketing', 'http://localhost:8000/products/lush-data-scraper', 'index, follow'),
(5, 1, 'LushChat AI Bot', 'lush-chatbot-ai', 'Trợ lý AI đa kênh phản hồi tin nhắn khách hàng thông minh theo ngữ cảnh', 'Ứng dụng trí tuệ nhân tạo thế hệ mới (LLM) để hiểu sâu ngữ cảnh khách hàng, tư vấn sản phẩm và tạo đơn hàng tự động ngay trong khung chat mà không cần nhân viên can thiệp.', '<h2>Đột phá trải nghiệm khách hàng với Trợ lý AI</h2><p>Lush Chatbot AI học hiểu toàn bộ tài liệu sản phẩm và chính sách công ty của bạn chỉ trong 5 phút. Tự tin trả lời khách hàng mượt mà như một chuyên viên tư vấn hàng đầu.</p>', NULL, 'images/products/LushChat.png', NULL, 'v3.0.0', NULL, 1, 'published', 15202, 5, '{"en":{"name":"Lush Chatbot AI","tagline":"Advanced automation and software ecosystem for scalable business growth.","description":"Empower your team with next-generation automation tools. High performance, zero setup friction, and enterprise-grade security."},"zh":{"name":"Lush Chatbot AI","tagline":"\\u52a9\\u529b\\u4f01\\u4e1a\\u9ad8\\u6548\\u589e\\u957f\\u7684\\u4e0b\\u4e00\\u4ee3\\u8f6f\\u4ef6\\u4e0e\\u81ea\\u52a8\\u5316\\u751f\\u6001\\u7cfb\\u7edf\\u3002","description":"\\u901a\\u8fc7\\u884c\\u4e1a\\u9886\\u5148\\u7684\\u8425\\u9500\\u4e0e\\u5ba2\\u6237\\u5173\\u7cfb\\u81ea\\u52a8\\u5316\\u5de5\\u5177\\u8d4b\\u80fd\\u4e1a\\u52a1\\uff0c\\u517c\\u5177\\u9876\\u7ea7\\u6027\\u80fd\\u4e0e\\u4f01\\u4e1a\\u7ea7\\u5b89\\u5168\\u6027\\u3002"},"ko":{"name":"Lush Chatbot AI","tagline":"\\ube44\\uc988\\ub2c8\\uc2a4 \\ud655\\uc7a5\\uc744 \\uc704\\ud55c \\ucc28\\uc138\\ub300 \\uc790\\ub3d9\\ud654 \\uc18c\\ud504\\ud2b8\\uc6e8\\uc5b4 \\uc194\\ub8e8\\uc158.","description":"\\uace0\\uc131\\ub2a5, \\uc644\\ubcbd\\ud55c \\ubcf4\\uc548, \\uc190\\uc26c\\uc6b4 \\uc0ac\\uc6a9\\uc131\\uc744 \\uac16\\ucd98 \\uc885\\ud569 \\ub9c8\\ucf00\\ud305 \\ubc0f CRM \\uc790\\ub3d9\\ud654 \\ud50c\\ub7ab\\ud3fc\\uc785\\ub2c8\\ub2e4."}}', '2026-10-30 14:15:33', '2026-11-02 01:44:16', 'LushChat AI Bot – Trợ Lý AI Đa Kênh Chốt Đơn Tự Động 24/7', 'Chatbot ứng dụng công nghệ trí tuệ nhân tạo AI Agent, thấu hiểu ngữ cảnh khách hàng, tự động tư vấn sản phẩm và xin thông tin chốt đơn 24/7.', 'chatbot ai da kenh, lushchat ai bot, tro ly ai ban hang, chatbot chot don tu dong', 'chatbot ai da kenh', 'http://localhost:8000/products/lush-chatbot-ai', 'index, follow'),
(6, 1, 'LushShopee Booster', 'lush-traffic-booster', 'Tự động hóa tăng tương tác, kéo traffic ngoại sàn và đẩy top gian hàng TMĐT', 'Hệ thống hỗ trợ kiểm toán website toàn diện, đề xuất từ khóa tiềm năng và theo dõi biến động thứ hạng từ khóa trên Google Search Console theo thời gian thực.', '<h2>Chinh phục vị trí top đầu công cụ tìm kiếm</h2><p>Phần mềm giúp chủ website và SEOer phát hiện ngay lập tức các lỗi kỹ thuật, liên kết gãy và cơ hội tối ưu nội dung chuẩn SEO để bùng nổ traffic tự nhiên.</p>', NULL, 'images/products/LushShopee.png', NULL, 'v2.1.2', NULL, 0, 'published', 6700, 6, '{"en":{"name":"Lush Traffic Booster","tagline":"Advanced automation and software ecosystem for scalable business growth.","description":"Empower your team with next-generation automation tools. High performance, zero setup friction, and enterprise-grade security."},"zh":{"name":"Lush Traffic Booster","tagline":"\\u52a9\\u529b\\u4f01\\u4e1a\\u9ad8\\u6548\\u589e\\u957f\\u7684\\u4e0b\\u4e00\\u4ee3\\u8f6f\\u4ef6\\u4e0e\\u81ea\\u52a8\\u5316\\u751f\\u6001\\u7cfb\\u7edf\\u3002","description":"\\u901a\\u8fc7\\u884c\\u4e1a\\u9886\\u5148\\u7684\\u8425\\u9500\\u4e0e\\u5ba2\\u6237\\u5173\\u7cfb\\u81ea\\u52a8\\u5316\\u5de5\\u5177\\u8d4b\\u80fd\\u4e1a\\u52a1\\uff0c\\u517c\\u5177\\u9876\\u7ea7\\u6027\\u80fd\\u4e0e\\u4f01\\u4e1a\\u7ea7\\u5b89\\u5168\\u6027\\u3002"},"ko":{"name":"Lush Traffic Booster","tagline":"\\ube44\\uc988\\ub2c8\\uc2a4 \\ud655\\uc7a5\\uc744 \\uc704\\ud55c \\ucc28\\uc138\\ub300 \\uc790\\ub3d9\\ud654 \\uc18c\\ud504\\ud2b8\\uc6e8\\uc5b4 \\uc194\\ub8e8\\uc158.","description":"\\uace0\\uc131\\ub2a5, \\uc644\\ubcbd\\ud55c \\ubcf4\\uc548, \\uc190\\uc26c\\uc6b4 \\uc0ac\\uc6a9\\uc131\\uc744 \\uac16\\ucd98 \\uc885\\ud569 \\ub9c8\\ucf00\\ud305 \\ubc0f CRM \\uc790\\ub3d9\\ud654 \\ud50c\\ub7ab\\ud3fc\\uc785\\ub2c8\\ub2e4."}}', '2026-10-30 14:15:33', '2026-11-02 01:44:16', 'LushShopee Booster – Phần Mềm Kéo Traffic & Bùng Nổ Đơn Hàng TMĐT', 'Tự động kéo hàng chục nghìn lượt truy cập ngoại sàn chất lượng cao về gian hàng Shopee/Lazada, giúp đẩy top đề xuất và bùng nổ doanh số bán hàng.', 'keo traffic shopee ngoai san, lushshopee booster, tang don hang shopee, ban hang san tmdt', 'keo traffic shopee ngoai san', 'http://localhost:8000/products/lush-traffic-booster', 'index, follow'),
(7, 1, 'LushTikTok Auto Viral', 'lush-tiktok-auto-viral', 'Tự động hóa reup, render video AI không đụng hàng và kéo view TikTok Shop', 'Giải pháp toàn diện cho nhà sáng tạo nội dung và nhà bán hàng TikTok Shop: tự động tải video không logo, lách bản quyền video bằng thuật toán AI biến đổi khung hình, tự động đăng tải và tương tác nuôi dưỡng tài khoản viral.', NULL, NULL, NULL, NULL, 'v2.0.0', 'https://lushsoftware.vn/downloads', 1, 'published', 1, 7, NULL, '2026-11-02 01:44:16', '2026-11-02 01:49:16', 'LushTikTok Auto Viral – Phần Mềm Reup & Nuôi Kênh TikTok Tự Động', 'Tự động hóa render video AI lách bản quyền, tự động đăng bài đa kênh TikTok Shop và tương tác kéo hàng triệu view hoàn toàn tự động.', 'phan mem tiktok tu dong, lushtiktok auto viral, reup video tiktok ai, keo view tiktok shop', 'phan mem tiktok tu dong', 'http://localhost:8000/products/lush-tiktok-auto-viral', 'index, follow'),
(8, 4, 'LushTelegram Lead Hunter', 'lush-telegram-lead-hunter', 'Quét thành viên nhóm mục tiêu và tự động gửi tin nhắn chăm sóc Telegram B2B', 'Công cụ trích xuất dữ liệu thành viên nhóm Telegram chất lượng cao, tự động lọc người dùng online gần nhất và gửi tin nhắn giới thiệu dịch vụ tài chính, crypto, e-commerce với độ an toàn cao.', NULL, NULL, NULL, NULL, 'v1.8.5', 'https://lushsoftware.vn/downloads', 1, 'published', 1, 8, NULL, '2026-11-02 01:44:16', '2026-11-02 01:49:17', 'LushTelegram Lead Hunter – Quét Dữ Liệu & Gửi Tin Telegram B2B', 'Quét thành viên nhóm Telegram tự động, trích xuất data khách hàng tiềm năng và tự động gửi tin nhắn tiếp thị B2B an toàn tuyệt đối.', 'phan mem telegram marketing, lushtelegram lead hunter, quet thanh vien telegram, marketing b2b', 'phan mem telegram marketing', 'http://localhost:8000/products/lush-telegram-lead-hunter', 'index, follow');

