(7, 4, 'Gói Bán Niên', 2200000, '₫', 'yearly', 1, '["Kh\\u00f4ng gi\\u1edbi h\\u1ea1n b\\u1ea3n ghi qu\\u00e9t","C\\u1eadp nh\\u1eadt m\\u1eabu qu\\u00e9t li\\u00ean t\\u1ee5c","Xu\\u1ea5t file Excel \\/ CSV t\\u1ed1c \\u0111\\u1ed9 cao"]', 'Đăng ký ngay', '/contact?product=lush-data-scraper', 1, '2026-10-30 14:15:33', '2026-10-30 14:15:33'),
(8, 5, 'Gói Tăng Trưởng', 4200000, '₫', 'yearly', 1, '["Ph\\u1ea3n h\\u1ed3i kh\\u00f4ng gi\\u1edbi h\\u1ea1n l\\u01b0\\u1ee3t chat","K\\u1ebft n\\u1ed1i Fanpage + Website Widget","Hu\\u1ea5n luy\\u1ec7n AI v\\u1edbi d\\u1eef li\\u1ec7u ri\\u00eang","H\\u1ed7 tr\\u1ee3 k\\u1ef9 thu\\u1eadt 24\\/7"]', 'Trải nghiệm AI', '/contact?product=lush-chatbot-ai', 1, '2026-10-30 14:15:33', '2026-10-30 14:15:33'),
(9, 6, 'Gói Chuyên Viên', 1950000, '₫', 'yearly', 1, '["Theo d\\u00f5i 500 t\\u1eeb kh\\u00f3a","Ki\\u1ec3m to\\u00e1n 5 website","B\\u00e1o c\\u00e1o t\\u1ef1 \\u0111\\u1ed9ng g\\u1eedi email h\\u00e0ng tu\\u1ea7n"]', 'Sử dụng ngay', '/contact?product=lush-traffic-booster', 1, '2026-10-30 14:15:33', '2026-10-30 14:15:33'),
(10, 7, 'Gói Trải Nghiệm 1 Tháng', 450000, 'đ', 'monthly', 0, '["S\\u1eed d\\u1ee5ng full t\\u00ednh n\\u0103ng tr\\u00ean 1 m\\u00e1y t\\u00ednh","Kh\\u00f4ng gi\\u1edbi h\\u1ea1n s\\u1ed1 l\\u01b0\\u1ee3ng t\\u00e1c v\\u1ee5","H\\u1ed7 tr\\u1ee3 k\\u1ef9 thu\\u1eadt Ultraview gi\\u1edd h\\u00e0nh ch\\u00ednh","C\\u1eadp nh\\u1eadt t\\u00ednh n\\u0103ng m\\u1edbi mi\\u1ec5n ph\\u00ed"]', 'Đăng ký ngay', NULL, 1, '2026-11-02 01:44:16', '2026-11-02 01:44:16'),
