INSERT INTO `product_faqs` (`id`, `product_id`, `question`, `answer`, `order`, `translations`, `created_at`, `updated_at`) VALUES
(1, 1, 'Phần mềm Lush Marketing Pro có cần cài đặt phần cứng đặc biệt không?', 'Không, Lush Marketing Pro hoạt động hoàn toàn trên nền tảng đám mây và tương thích trên mọi trình duyệt web hiện đại (Chrome, Edge, Safari, Firefox).', 1, NULL, '2026-10-30 14:15:33', '2026-10-30 14:15:33'),
(2, 1, 'Tôi có được hỗ trợ chuyển đổi dữ liệu từ phần mềm cũ không?', 'Có, đội ngũ chuyên gia của LushSoftware sẽ trực tiếp đồng hành cùng doanh nghiệp bạn trong quá trình import dữ liệu và thiết lập ban đầu hoàn toàn miễn phí.', 2, NULL, '2026-10-30 14:15:33', '2026-10-30 14:15:33'),
(3, 1, 'Hệ thống có cam kết bảo mật thông tin khách hàng không?', 'Chắc chắn có. Chúng tôi áp dụng quy chuẩn bảo mật mã hóa end-to-end và cam kết tuyệt đối không chia sẻ dữ liệu với bên thứ ba dưới bất kỳ hình thức nào.', 3, NULL, '2026-10-30 14:15:33', '2026-10-30 14:15:33'),
(4, 2, 'Có sợ bị khóa tài khoản khi dùng phần mềm không?', 'Lush Social Hub sử dụng công nghệ giả lập hành vi người dùng chuẩn xác với IP sạch và cơ chế giãn cách an toàn, hạn chế tối đa rủi ro checkpoint.', 1, NULL, '2026-10-30 14:15:33', '2026-10-30 14:15:33'),
(5, 3, 'Dữ liệu khách hàng trên CRM có thể xuất ra file Excel được không?', 'Có, bạn hoàn toàn có thể phân quyền ai được phép xuất dữ liệu ra định dạng Excel hoặc CSV với mã OTP xác thực an toàn.', 1, NULL, '2026-10-30 14:15:33', '2026-10-30 14:15:33'),
(6, 4, 'Dữ liệu quét về có chính xác không?', 'Dữ liệu được lấy trực tiếp theo thời gian thực từ các nguồn công khai nên độ chính xác đạt tới 99%.', 1, NULL, '2026-10-30 14:15:33', '2026-10-30 14:15:33'),
(7, 5, 'AI có bị nói sai hoặc bịa đặt thông tin không?', 'Lush Chatbot AI được trang bị cơ chế kiểm soát ngữ cảnh nghiêm ngặt (RAG), chỉ trả lời dựa trên kho tri thức chính xác mà bạn cung cấp.', 1, NULL, '2026-10-30 14:15:33', '2026-10-30 14:15:33'),
(8, 6, 'Phần mềm có hỗ trợ theo dõi theo từng vị trí địa lý không?', 'Có, Lush Traffic Booster hỗ trợ kiểm tra thứ hạng theo tỉnh/thành phố cụ thể.', 1, NULL, '2026-10-30 14:15:33', '2026-10-30 14:15:33'),
(9, 7, 'Sau khi thanh toán bao lâu thì tôi nhận được bản quyền phần mềm LushTikTok Auto Viral?', 'Hệ thống kích hoạt bản quyền tự động ngay sau khi quét mã VietQR. Bạn sẽ nhận key qua email và kỹ sư LushSoftware sẽ liên hệ hỗ trợ cài đặt Ultraview trong 5 - 15 phút.', 1, NULL, '2026-11-02 01:44:16', '2026-11-02 01:44:16'),
(10, 7, 'Tôi có được hỗ trợ cài đặt và hướng dẫn sử dụng không?', 'Có. Đội ngũ kỹ thuật viên LushSoftware cam kết hỗ trợ 1-1 qua Ultraview / AnyDesk / Zalo trong suốt thời gian bạn sử dụng phần mềm.', 2, NULL, '2026-11-02 01:44:16', '2026-11-02 01:44:16'),
(11, 8, 'Sau khi thanh toán bao lâu thì tôi nhận được bản quyền phần mềm LushTelegram Lead Hunter?', 'Hệ thống kích hoạt bản quyền tự động ngay sau khi quét mã VietQR. Bạn sẽ nhận key qua email và kỹ sư LushSoftware sẽ liên hệ hỗ trợ cài đặt Ultraview trong 5 - 15 phút.', 1, NULL, '2026-11-02 01:44:16', '2026-11-02 01:44:16'),
(12, 8, 'Tôi có được hỗ trợ cài đặt và hướng dẫn sử dụng không?', 'Có. Đội ngũ kỹ thuật viên LushSoftware cam kết hỗ trợ 1-1 qua Ultraview / AnyDesk / Zalo trong suốt thời gian bạn sử dụng phần mềm.', 2, NULL, '2026-11-02 01:44:16', '2026-11-02 01:44:16');

