(1, 'Trần Minh Hoàng', 'Giám đốc Marketing', 'TechGrowth Media', NULL, 'Lush Marketing Pro đã thực sự thay đổi cách đội ngũ của chúng tôi vận hành. Trước đây chúng tôi mất 4 tiếng mỗi ngày để xử lý dữ liệu và gửi thông điệp, giờ đây mọi thứ diễn ra tự động với độ chính xác tuyệt đối.', 5, 1, 1, '2026-10-30 14:15:33', '2026-10-30 14:15:33'),
(2, 'Nguyễn Bích Ngọc', 'Founder & CEO', 'Aura Cosmetics', NULL, 'Giao diện cực kỳ trực quan, sạch sẽ và chuyên nghiệp. Tôi ấn tượng nhất với tốc độ xử lý và sự nhiệt tình của đội ngũ hỗ trợ kỹ thuật LushSoftware. Đây chắc chắn là giải pháp tốt nhất trong tầm giá.', 5, 2, 1, '2026-10-30 14:15:33', '2026-10-30 14:15:33'),
(3, 'David Phạm', 'Trưởng phòng Kinh Doanh', 'Việt Á Real Estate', NULL, 'Hệ thống Lush CRM Enterprise giúp tỷ lệ chốt đơn của đội ngũ chúng tôi tăng hơn 40% trong quý vừa qua nhờ tính năng chia lead thông minh và theo dõi phễu bán hàng theo thời gian thực.', 5, 3, 1, '2026-10-30 14:15:33', '2026-10-30 14:15:33');

